-- Product categories
insert into public.product_categories (
  slug, icon, name_ar, name_en, short_ar, short_en, description_ar, description_en, cover_image, certs, standards,
  sizes_label_ar, sizes_label_en, pressure_label_ar, pressure_label_en, brands, specs,
  items_ar, items_en, applications_ar, applications_en, brochure, sort_order
) values (
  'pipes', 'pipe', 'مواسير صلب كربون سيملس', 'Seamless Carbon Steel Pipes', 'مواسير سيملس سوداء ومجلفنة من ½" حتى 12" – من MECH Plumnect وINTERPIPE ومنشأ صيني.', 'Black and galvanized seamless pipes from ½" to 12" – MECH Plumnect, INTERPIPE and Chinese origin.', 'مواسير صلب كربون سيملس بدون خط لحام لضمان بنية متجانسة وقوة عالية تحت الضغط. متوفرة سوداء أو مجلفنة بجدول 40، ومعتمدة UL لشبكات الحريق الرطبة والجافة والدلوج وما قبل التفعيل، بالإضافة لخطوط المياه والبترول والهواء.', 'Weld-free seamless carbon steel pipes with a uniform structure and high pressure strength. Available black or galvanized in Schedule 40, UL Listed for wet, dry, deluge and pre-action fire networks as well as water, oil and air lines.', '/images/catalog/cover-pipes.jpg', array['UL', 'NFPA', 'ISO']::text[], 'ASTM A53 / A106 Grade B',
  '½" – 12" · جدول 40', '½" – 12" · SCH 40', 'حتى 300 PSI لأنظمة الحريق', 'Up to 300 PSI for fire service', '[{"name_ar":"MECH Plumnect","name_en":"MECH Plumnect"},{"name_ar":"INTERPIPE","name_en":"INTERPIPE"},{"name_ar":"منشأ صيني","name_en":"Chinese Origin"}]'::jsonb, '[{"label_ar":"نوع التصنيع","label_en":"Manufacturing","value_ar":"سيملس – تقنية PQF","value_en":"Seamless – PQF process"},{"label_ar":"السُمك","label_en":"Wall","value_ar":"Schedule 40","value_en":"Schedule 40"},{"label_ar":"النهايات","label_en":"Ends","value_ar":"سادة / مجرّاة / مسننة","value_en":"Plain / Grooved / Threaded"},{"label_ar":"الطول","label_en":"Length","value_ar":"6 متر","value_en":"6 m"}]'::jsonb,
  array['مواسير سيملس سوداء', 'مواسير سيملس مجلفنة']::text[], array['Black seamless pipes', 'Galvanized seamless pipes']::text[], array['شبكات الرشاشات الرطبة والجافة', 'أنظمة الدلوج وما قبل التفعيل', 'خطوط المياه', 'خطوط البترول والغاز والهواء']::text[], array['Wet & dry sprinkler networks', 'Deluge & pre-action systems', 'Water lines', 'Oil, gas & air lines']::text[], array['/images/brochure/mech-pipe.jpg', '/images/brochure/interpipe.jpg']::text[], 0
) on conflict (slug) do nothing;
insert into public.product_categories (
  slug, icon, name_ar, name_en, short_ar, short_en, description_ar, description_en, cover_image, certs, standards,
  sizes_label_ar, sizes_label_en, pressure_label_ar, pressure_label_en, brands, specs,
  items_ar, items_en, applications_ar, applications_en, brochure, sort_order
) values (
  'fittings', 'fitting', 'وصلات المواسير', 'Pipe Fittings', 'أربعة أنواع: لحام تناكبي، مسننة، مجرّاة، ومطروقة عالية الضغط – أكواع وتيهات ومسلوبات وبوش.', 'Four types: butt-weld, threaded, grooved and forged high-pressure – elbows, tees, reducers and bushings.', 'تشكيلة كاملة من وصلات المواسير لكل طريقة توصيل: وصلات اللحام التناكبي من TTU، والمسننة من MECH وSA، والمجرّاة من MECH (الوكيل الحصري)، والمطروقة عالية الضغط من Both-Well المعتمدة من أرامكو وأدنوك.', 'A complete range for every joining method: TTU butt-weld fittings, MECH and SA threaded fittings, MECH grooved fittings (exclusive agent) and Both-Well forged high-pressure fittings approved by Aramco and ADNOC.', '/images/catalog/cover-fittings.jpg', array['UL', 'FM', 'ISO']::text[], 'ASME B16.9 · B16.3 · B16.11 · ASTM A536',
  '½" – 12" حسب النوع', '½" – 12" depending on type', 'حتى 300 PSI · مطروقة 3000#', 'Up to 300 PSI · forged 3000#', '[{"name_ar":"TTU Thailand","name_en":"TTU Thailand"},{"name_ar":"MECH","name_en":"MECH"},{"name_ar":"SA – Siam Fittings","name_en":"SA – Siam Fittings"},{"name_ar":"Both-Well","name_en":"Both-Well"}]'::jsonb, '[{"label_ar":"الأنواع","label_en":"Types","value_ar":"لحام / مسنن / مجرّى / مطروق","value_en":"Butt-weld / threaded / grooved / forged"},{"label_ar":"الأشكال","label_en":"Shapes","value_ar":"كوع، تي، مسلوب، بوش","value_en":"Elbow, tee, reducer, bushing"},{"label_ar":"الخامات","label_en":"Materials","value_ar":"صلب كربوني / حديد مطاوع / دكتايل","value_en":"Carbon steel / malleable / ductile iron"}]'::jsonb,
  array['وصلات لحام تناكبي', 'وصلات مسننة', 'وصلات مجرّاة', 'وصلات مطروقة عالية الضغط']::text[], array['Butt-weld fittings', 'Threaded fittings', 'Grooved fittings', 'Forged high-pressure fittings']::text[], array['شبكات الحريق', 'السباكة وشبكات المياه', 'البترول والغاز', 'محطات الطاقة والبتروكيماويات']::text[], array['Fire networks', 'Plumbing & waterworks', 'Oil & gas', 'Power & petrochemical plants']::text[], array['/images/brochure/ttu.jpg', '/images/brochure/mech-malleable.jpg', '/images/brochure/mech-grooved.jpg', '/images/brochure/bothwell.jpg', '/images/brochure/sa.jpg']::text[], 1
) on conflict (slug) do nothing;
insert into public.product_categories (
  slug, icon, name_ar, name_en, short_ar, short_en, description_ar, description_en, cover_image, certs, standards,
  sizes_label_ar, sizes_label_en, pressure_label_ar, pressure_label_en, brands, specs,
  items_ar, items_en, applications_ar, applications_en, brochure, sort_order
) values (
  'valves', 'valve', 'المحابس', 'Valves', 'محابس OS&Y ومحابس عدم الرجوع من MECH وReliable، ومحابس بلف واختبار وتصريف واتزان وفلاتر وتحكم مناطق.', 'MECH & Reliable OS&Y and check valves, plus ball, test & drain, balance, strainer and zone control valves.', 'كل ما تحتاجه غرفة المحابس وشبكة الحريق: محابس OS&Y البوابية ومحابس عدم الرجوع المعتمدة UL/FM من MECH وReliable، بالإضافة لمحابس البلف ومفاتيح المراقبة ومحابس الاختبار والتصريف ومحابس الاتزان والفلاتر ومجموعات التحكم في المناطق.', 'Everything a valve room and fire network needs: UL/FM OS&Y gate and check valves from MECH and Reliable, plus ball valves, tamper switches, test & drain, balance, strainer and zone control valves.', '/images/catalog/cover-valves.jpg', array['UL', 'FM']::text[], 'AWWA C515 · UL 262 · UL 312',
  '½" – 12" حسب النوع', '½" – 12" depending on type', '300 PSI (Reliable) · PN16 (MECH)', '300 PSI (Reliable) · PN16 (MECH)', '[{"name_ar":"MECH","name_en":"MECH"},{"name_ar":"Reliable","name_en":"Reliable"}]'::jsonb, '[{"label_ar":"التوصيل","label_en":"Ends","value_ar":"فلانشات / مجرّاة / مسننة","value_en":"Flanged / grooved / threaded"},{"label_ar":"الخامة","label_en":"Body","value_ar":"حديد دكتايل / نحاس","value_en":"Ductile iron / brass"},{"label_ar":"الدهان","label_en":"Coating","value_ar":"إيبوكسي أحمر","value_en":"Red epoxy"}]'::jsonb,
  array['محابس OS&Y', 'محابس عدم رجوع', 'محابس بلف', 'مفاتيح مراقبة Tamper', 'محابس اختبار وتصريف', 'محابس اتزان', 'فلاتر Strainer', 'تحكم مناطق Zone Control']::text[], array['OS&Y valves', 'Check valves', 'Ball valves', 'Tamper switches', 'Test & drain valves', 'Balance valves', 'Strainers', 'Zone control']::text[], array['غرف المحابس والصواعد', 'غرف المضخات', 'شبكات الرشاشات', 'أنظمة التكييف والمياه']::text[], array['Valve rooms & risers', 'Pump rooms', 'Sprinkler networks', 'HVAC & water systems']::text[], array['/images/brochure/mech-valves.jpg', '/images/brochure/reliable.jpg']::text[], 2
) on conflict (slug) do nothing;
insert into public.product_categories (
  slug, icon, name_ar, name_en, short_ar, short_en, description_ar, description_en, cover_image, certs, standards,
  sizes_label_ar, sizes_label_en, pressure_label_ar, pressure_label_en, brands, specs,
  items_ar, items_en, applications_ar, applications_en, brochure, sort_order
) values (
  'sprinklers', 'sprinkler', 'رشاشات الحريق', 'Fire Sprinklers', 'براندين MECH وReliable – ثلاثة أنواع لكل براند، وكل نوع بثلاثة أشكال: متدلي وقائم وجانبي.', 'Two brands, MECH and Reliable – three types each, every type in three styles: pendent, upright and sidewall.', 'رشاشات معتمدة UL وFM بحساسية حرارية دقيقة واستجابة سريعة للسيطرة على انتشار الحريق، مع مقاومة عالية للتآكل. متوفرة بدرجات حرارة 68° و79° و93° مئوية.', 'UL Listed & FM Approved sprinklers with precise thermal sensing and rapid response to control fire spread, with high corrosion resistance. Available in 68°, 79° and 93°C ratings.', '/images/catalog/cover-sprinklers.jpg', array['UL', 'FM']::text[], 'UL 199 · NFPA 13',
  '½" NPT K5.6 · ¾" NPT K8.0', '½" NPT K5.6 · ¾" NPT K8.0', 'حتى 175 PSI', 'Up to 175 PSI', '[{"name_ar":"MECH","name_en":"MECH"},{"name_ar":"Reliable","name_en":"Reliable"}]'::jsonb, '[{"label_ar":"الأشكال","label_en":"Styles","value_ar":"متدلي / قائم / جانبي","value_en":"Pendent / Upright / Sidewall"},{"label_ar":"درجات التشغيل","label_en":"Temperatures","value_ar":"68°C · 79°C · 93°C","value_en":"68°C · 79°C · 93°C"},{"label_ar":"التشطيب","label_en":"Finish","value_ar":"نحاسي / كروم / أبيض","value_en":"Brass / chrome / white"}]'::jsonb,
